public class Main {static class Fast {byte[] b=new byte[65536];int p,l;int read()throws Exception{if(p==l){l=System.in.read(b);p=0;if(l<0)return -1;}return b[p++];}long next()throws Exception{int c;do{c=read();}while(c<=32&&c!=-1);long x=0;while(c>32){x=x*10+c-48;c=read();}return x;}}
 static boolean reaches(int[] a,int mask){if((a[0]&mask)!=a[0]||(a[a.length-1]&mask)!=a[a.length-1])return false;int reach=0;for(int i=0;i<a.length&&i<=reach;i++)if((a[i]&mask)==a[i])reach=Math.max(reach,i+a[i]);return reach>=a.length-1;}
 public static void main(String[] args)throws Exception{Fast in=new Fast();int t=(int)in.next();StringBuilder out=new StringBuilder();while(t-->0){int n=(int)in.next();int[] a=new int[n];for(int i=0;i<n;i++)a[i]=(int)in.next();int mask=(1<<19)-1;if(!reaches(a,mask)){out.append(-1).append('\n');continue;}for(int bit=18;bit>=0;bit--){int trial=mask&~(1<<bit);if(reaches(a,trial))mask=trial;}out.append(mask).append('\n');}System.out.print(out);}}
